<!doctype html>
<html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northwind BMS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@400;500;600;700&display=swap" rel="stylesheet"><style>
:root{--bg:#f0f4f8;--paper:#fff;--line:#e2e8f0;--ink:#0f172a;--muted:#64748b;--blue:#2563eb;--pale:#eff6ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Sarabun,system-ui,sans-serif}button,input,select{font:inherit}.layout{min-height:100vh;display:flex}.side{width:235px;background:var(--paper);border-right:1px solid var(--line);padding:20px 14px;position:fixed;inset:0 auto 0 0;overflow:auto}.brand{font-size:17px;font-weight:700;padding:8px 10px 24px}.brand span{display:inline-grid;place-items:center;background:var(--blue);color:white;border-radius:9px;width:34px;height:34px;margin-right:8px}.group{color:#94a3b8;text-transform:uppercase;font-size:11px;margin:16px 10px 7px}.nav{width:100%;border:0;background:transparent;text-align:left;padding:9px 11px;border-radius:8px;color:#475569;cursor:pointer}.nav:hover,.nav.active{background:var(--pale);color:var(--blue);font-weight:700}.main{margin-left:235px;width:calc(100% - 235px)}.top{height:58px;background:white;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;padding:0 25px;position:sticky;top:0;z-index:2}.content{padding:25px;max-width:1450px;margin:auto}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.heading h1{font-size:23px;margin:0}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.kpi,.card{background:white;border:1px solid var(--line);border-radius:12px;padding:18px}.kpi label{color:var(--muted);display:block}.kpi strong{font-size:25px}.card{margin-bottom:16px}.toolbar{display:flex;gap:8px;margin-bottom:13px}.toolbar input{flex:1}.input,select{border:1px solid var(--line);background:white;border-radius:8px;padding:9px 11px;color:var(--ink)}.btn{border:0;border-radius:8px;background:var(--blue);color:#fff;padding:9px 14px;cursor:pointer}.btn.secondary{background:#fff;color:#334155;border:1px solid var(--line)}.btn.danger{background:#dc2626}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid #edf1f5;white-space:nowrap}th{color:var(--muted);font-weight:600;font-size:12px;background:#f8fafc}td .btn{padding:5px 9px;margin-right:4px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}.bar{display:flex;align-items:center;gap:9px;margin:9px 0}.bar label{width:145px;overflow:hidden;text-overflow:ellipsis}.track{height:9px;flex:1;background:#e8eef8;border-radius:9px}.fill{height:100%;background:#3b82f6;border-radius:9px}.modal{position:fixed;inset:0;background:#0f172a88;display:none;align-items:center;justify-content:center;z-index:10;padding:20px}.dialog{background:white;border-radius:14px;padding:22px;width:min(600px,100%);max-height:90vh;overflow:auto}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}.field input{width:100%}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.notice{padding:10px 12px;border-radius:8px;background:#fee2e2;color:#991b1b;margin-bottom:12px;display:none}#login{position:fixed;inset:0;background:var(--bg);z-index:20;display:none;place-items:center}.loginbox{background:white;padding:30px;border:1px solid var(--line);border-radius:14px;width:min(390px,92vw)}.loginbox input{width:100%;margin:8px 0 13px}.small{font-size:12px}@media(max-width:850px){.side{width:64px;padding:12px 7px}.brand{padding:6px}.brand .brandtxt,.group,.nav span{display:none}.nav{text-align:center}.main{margin-left:64px;width:calc(100% - 64px)}.grid{grid-template-columns:repeat(2,1fr)}.content{padding:15px}.two{grid-template-columns:1fr}}@media(max-width:520px){.grid{grid-template-columns:1fr 1fr}.fields{grid-template-columns:1fr}.top{padding:0 12px}}
</style></head><body>
<div id="login"><form class="loginbox" onsubmit="login(event)"><h2>เข้าสู่ระบบ Northwind</h2><p class="muted">ระบบจัดการธุรกิจ</p><div id="loginError" class="notice"></div><label>ชื่อผู้ใช้</label><input class="input" name="username" value="admin" required><label>รหัสผ่าน</label><input class="input" name="password" type="password" required><button class="btn" style="width:100%">เข้าสู่ระบบ</button><p class="small muted">บัญชีเริ่มต้นสำหรับติดตั้งใหม่: admin / ChangeMe123!</p></form></div>
<div class="layout"><aside class="side"><div class="brand"><span>NW</span><span class="brandtxt">Northwind BMS</span></div><div class="group">ภาพรวม</div><button class="nav active" data-page="dashboard">▦ <span>แดชบอร์ด</span></button><div class="group">จัดการข้อมูล</div><button class="nav" data-page="products">▣ <span>สินค้า</span></button><button class="nav" data-page="categories">◫ <span>หมวดหมู่สินค้า</span></button><button class="nav" data-page="orders">▤ <span>คำสั่งซื้อ</span></button><button class="nav" data-page="customers">♙ <span>ลูกค้า</span></button><button class="nav" data-page="suppliers">♧ <span>ผู้จัดจำหน่าย</span></button><button class="nav" data-page="employees">♟ <span>พนักงาน</span></button><button class="nav" data-page="shippers">➤ <span>บริษัทขนส่ง</span></button><div class="group">วิเคราะห์</div><button class="nav" data-page="reports">▥ <span>รายงาน</span></button></aside><main class="main"><header class="top"><span id="crumb">แดชบอร์ดภาพรวม</span><span id="who" class="muted"></span></header><div class="content"><div id="app"></div></div></main></div>
<div id="modal" class="modal"><form class="dialog" onsubmit="save(event)"><h2 id="modalTitle">แก้ไข</h2><div id="formFields" class="fields"></div><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">ยกเลิก</button><button class="btn">บันทึกข้อมูล</button></div></form></div>
<script>
const defs={products:{title:'รายการสินค้า',entity:'products',pk:'i_ProductID',fields:[['c_ProductName','ชื่อสินค้า'],['i_SupplierID','รหัสผู้จัดจำหน่าย','number'],['i_CategoryID','รหัสหมวดหมู่','number'],['c_Unit','หน่วยบรรจุ'],['i_Price','ราคา','number']]},categories:{title:'หมวดหมู่สินค้า',entity:'categories',pk:'i_CategoryID',fields:[['c_CategoryName','ชื่อหมวดหมู่'],['c_Description','รายละเอียด']]},customers:{title:'ทะเบียนลูกค้า',entity:'customers',pk:'i_customerid',fields:[['c_customername','ชื่อลูกค้า'],['c_contactname','ผู้ติดต่อ'],['c_address','ที่อยู่'],['c_city','เมือง'],['c_postalcode','รหัสไปรษณีย์'],['c_country','ประเทศ']]},suppliers:{title:'ทะเบียนผู้จัดจำหน่าย',entity:'suppliers',pk:'i_SupplierID',fields:[['c_SupplierName','ชื่อบริษัท'],['c_ContactName','ผู้ติดต่อ'],['c_Address','ที่อยู่'],['c_City','เมือง'],['c_PostalCode','รหัสไปรษณีย์'],['c_Country','ประเทศ'],['c_Phone','โทรศัพท์']]},employees:{title:'รายชื่อพนักงาน',entity:'employees',pk:'i_EmployeeID',fields:[['c_LastName','นามสกุล'],['c_FirstName','ชื่อ'],['c_BirthDate','วันเกิด'],['c_Photo','ไฟล์รูป'],['c_Notes','หมายเหตุ']]},shippers:{title:'บริษัทขนส่ง',entity:'shippers',pk:'i_ShipperID',fields:[['c_ShipperName','ชื่อบริษัท'],['c_Phone','โทรศัพท์']]},orders:{title:'รายการคำสั่งซื้อ',entity:'orders'}};
let page='dashboard',editing=null;const app=document.querySelector('#app');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,data=null,query=''){const r=await fetch(`api.php?action=${action}${query}`,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'เกิดข้อผิดพลาด');return j}
async function boot(){try{const d=await api('me');if(!d.user){document.querySelector('#login').style.display='grid';return}document.querySelector('#who').innerHTML=`${esc(d.user.name)} <button class="btn secondary" onclick="logout()">ออกจากระบบ</button>`;render()}catch(e){app.innerHTML=`<div class="card">${esc(e.message)}<br>นำเข้าไฟล์ SQL และตั้งค่า config.php ก่อนใช้งาน</div>`}}
async function login(e){e.preventDefault();const f=new FormData(e.target);try{await api('login',{username:f.get('username'),password:f.get('password')});document.querySelector('#login').style.display='none';document.querySelector('#loginError').style.display='none';boot()}catch(x){const n=document.querySelector('#loginError');n.textContent=x.message;n.style.display='block'}}async function logout(){await api('logout');location.reload()}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');page=b.dataset.page;render()});
async function render(){const d=defs[page];document.querySelector('#crumb').textContent=d?.title||'แดชบอร์ดภาพรวม';if(page==='dashboard'||page==='reports'){try{let x=await api('dashboard');app.innerHTML=`<div class="heading"><div><h1>${page==='reports'?'รายงานและวิเคราะห์ข้อมูล':'แดชบอร์ดภาพรวม'}</h1><span class="muted">ภาพรวมข้อมูลจากฐานข้อมูล Northwind</span></div><button class="btn secondary" onclick="downloadCsv()">ส่งออก CSV</button></div><div class="grid">${[['สินค้า',x.products],['คำสั่งซื้อ',x.orders],['ลูกค้า',x.customers],['รายได้โดยประมาณ','฿'+Number(x.revenue).toLocaleString(undefined,{maximumFractionDigits:0})]].map(a=>`<div class="kpi"><label>${a[0]}</label><strong>${a[1]}</strong></div>`).join('')}</div><div class="two" style="margin-top:16px"><div class="card"><h3>สินค้าขายดีตามจำนวน</h3>${bars(x.topProducts,'name','quantity')}</div><div class="card"><h3>ลูกค้าที่มีคำสั่งซื้อมาก</h3>${bars(x.topCustomers,'name','orders')}</div></div>`}catch(e){app.innerHTML=`<div class="card">${esc(e.message)}<br>ตรวจสอบว่าฐานข้อมูลนำเข้าแล้วและค่าเชื่อมต่อถูกต้อง</div>`}return}if(!d)return;app.innerHTML=`<div class="heading"><div><h1>${d.title}</h1><span class="muted">ค้นหาและจัดการข้อมูลในฐานข้อมูล</span></div>${d.fields?'<button class="btn" onclick="openForm()">＋ เพิ่มรายการ</button>':''}</div><section class="card"><div class="toolbar"><input id="search" class="input" placeholder="ค้นหา..." oninput="loadTable()"><button class="btn secondary" onclick="loadTable()">ค้นหา</button></div><div id="tableArea" class="tablewrap">กำลังโหลด...</div></section>`;loadTable()}
function bars(rows,n,v){let max=Math.max(1,...rows.map(r=>Number(r[v])));return rows.map(r=>`<div class="bar"><label title="${esc(r[n])}">${esc(r[n])}</label><div class="track"><div class="fill" style="width:${100*Number(r[v])/max}%"></div></div><b>${esc(r[v])}</b></div>`).join('')||'<p class="muted">ไม่มีข้อมูล</p>'}
async function loadTable(){const d=defs[page],a=document.querySelector('#tableArea');if(!d||!a)return;try{const rows=await api('list',null,`&entity=${d.entity}&q=${encodeURIComponent(document.querySelector('#search')?.value||'')}`);if(!rows.length){a.innerHTML='ไม่พบข้อมูล';return}if(page==='orders'){a.innerHTML=`<table><thead><tr><th>เลขที่</th><th>วันที่</th><th>ลูกค้า</th><th>พนักงาน</th><th>ขนส่ง</th><th>มูลค่า</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>#${r.i_OrderID}</td><td>${esc(r.c_OrderDate)}</td><td>${esc(r.c_customername)}</td><td>${esc(r.employee)}</td><td>${esc(r.c_ShipperName)}</td><td>${Number(r.total).toLocaleString()}</td><td><button class="btn secondary" onclick="orderDetail(${r.i_OrderID})">รายละเอียด</button></td></tr>`).join('')}</tbody></table>`;return}const keys=[d.pk,...d.fields.map(f=>f[0])];a.innerHTML=`<table><thead><tr>${keys.map(k=>`<th>${esc(k===d.pk?'รหัส':d.fields.find(f=>f[0]===k)[1])}</th>`).join('')}<th>จัดการ</th></tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}<td><button class="btn secondary" onclick="openForm('${encodeURIComponent(JSON.stringify(r))}')">แก้ไข</button><button class="btn danger" onclick="removeRow(${r[d.pk]})">ลบ</button></td></tr>`).join('')}</tbody></table>`}catch(e){a.textContent=e.message}}
function openForm(serialized=null){const d=defs[page];editing=serialized?JSON.parse(decodeURIComponent(serialized)):null;document.querySelector('#modalTitle').textContent=editing?'แก้ไขข้อมูล':'เพิ่มข้อมูล';document.querySelector('#formFields').innerHTML=d.fields.map(([key,label,type])=>`<div class="field"><label>${label}</label><input class="input" name="${key}" type="${type||'text'}" step="any" value="${esc(editing?.[key]??'')}" required></div>`).join('');document.querySelector('#modal').style.display='flex'}function closeModal(){document.querySelector('#modal').style.display='none'}async function save(e){e.preventDefault();const row={};new FormData(e.target).forEach((v,k)=>row[k]=v);try{await api('save',{entity:page,id:editing?.[defs[page].pk],row});closeModal();loadTable()}catch(x){alert(x.message)}}async function removeRow(id){if(!confirm('ยืนยันลบข้อมูลรายการนี้?'))return;try{await api('delete',{entity:page,id});loadTable()}catch(e){alert(e.message)}}async function orderDetail(id){try{const o=await api('detail',null,`&id=${id}`);app.innerHTML=`<div class="heading"><div><h1>คำสั่งซื้อ #${o.i_OrderID}</h1><span class="muted">${esc(o.c_OrderDate)} · ${esc(o.c_customername)} · ${esc(o.employee)}</span></div><button class="btn secondary" onclick="page='orders';render()">กลับไปรายการ</button></div><div class="card tablewrap"><table><thead><tr><th>สินค้า</th><th>ราคาต่อหน่วย</th><th>จำนวน</th><th>รวม</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.c_ProductName)}</td><td>${Number(i.i_Price).toFixed(2)}</td><td>${i.i_Quantity}</td><td>${Number(i.line_total).toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){alert(e.message)}}
async function downloadCsv(){const source=defs[page]||defs.orders;const rows=await api('list',null,`&entity=${source.entity}`);const keys=Object.keys(rows[0]||{});const csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=(defs[page]?page:'orders')+'.csv';a.click();URL.revokeObjectURL(a.href)}boot();
</script></body></html>
